const PI = 3.14159;
let radius = 7;
let area1 = PI * radius * radius;
console.log("مساحة الدائرة بنصف قطر 7: " + area1);
radius = 10;
let area2 = PI * radius * radius;
console.log("مساحة الدائرة بنصف قطر 10: " + area2);
